export type KolabPluginPdas = {
  config: typeof findConfigPda;
  approval: typeof findApprovalPda;
  enrollment: typeof findEnrollmentPda;
  saleReceipt: typeof findSaleReceiptPda;
};

export type KolabPluginRequirements = ClientWithRpc<GetAccountInfoApi & GetMultipleAccountsApi> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function kolabProgram() {
  return <T extends KolabPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { kolab: KolabPlugin }> => {
    return extendClient(client, {
      kolab: <KolabPlugin>{
        accounts: {
          approval: addSelfFetchFunctions(client, getApprovalCodec()),
          campaign: addSelfFetchFunctions(client, getCampaignCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          enrollment: addSelfFetchFunctions(client, getEnrollmentCodec()),
          saleReceipt: addSelfFetchFunctions(client, getSaleReceiptCodec()),
          slot: addSelfFetchFunctions(client, getSlotCodec()),
        },
        instructions: {
          allowMint: (input) =>
            addSelfPlanAndSendFunctions(client, getAllowMintInstructionAsync(input)),
          approve: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getApproveInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          approveCreator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getApproveCreatorInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          attestChecks: (input) =>
            addSelfPlanAndSendFunctions(client, getAttestChecksInstructionAsync(input)),
          attestLive: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAttestLiveInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          autoRelease: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAutoReleaseInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          cancelEnrollment: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelEnrollmentInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          claimSales: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimSalesInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          closeCampaign: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseCampaignInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          confirmReceived: (input) =>
            addSelfPlanAndSendFunctions(client, getConfirmReceivedInstructionAsync(input)),
          createCampaign: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateCampaignInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          enrollCreator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEnrollCreatorInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          fundCampaign: (input) =>
            addSelfPlanAndSendFunctions(client, getFundCampaignInstruction(input)),
          initConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getInitConfigInstructionAsync(input)),
          initSlot: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitSlotInstruction({ ...input, payer: input.payer ?? client.payer }),
            ),
          markMissed: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getMarkMissedInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          markShipped: (input) =>
            addSelfPlanAndSendFunctions(client, getMarkShippedInstructionAsync(input)),
          recordSale: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecordSaleInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          reject: (input) => addSelfPlanAndSendFunctions(client, getRejectInstructionAsync(input)),
          reportNotReceived: (input) =>
            addSelfPlanAndSendFunctions(client, getReportNotReceivedInstructionAsync(input)),
          revokeApproval: (input) =>
            addSelfPlanAndSendFunctions(client, getRevokeApprovalInstruction(input)),
          setDemoOffset: (input) =>
            addSelfPlanAndSendFunctions(client, getSetDemoOffsetInstructionAsync(input)),
          setVerifier: (input) =>
            addSelfPlanAndSendFunctions(client, getSetVerifierInstructionAsync(input)),
          submitDeliverable: (input) =>
            addSelfPlanAndSendFunctions(client, getSubmitDeliverableInstructionAsync(input)),
          topUpCampaign: (input) =>
            addSelfPlanAndSendFunctions(client, getTopUpCampaignInstruction(input)),
        },
        pdas: {
          config: findConfigPda,
          approval: findApprovalPda,
          enrollment: findEnrollmentPda,
          saleReceipt: findSaleReceiptPda,
        },
        identifyAccount: identifyKolabAccount,
        identifyInstruction: identifyKolabInstruction,
        parseInstruction: parseKolabInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
